return {
  ["Aide_Text_DontHaveAnyRoomForItem"] = "¡Oh! Ya veo que no tienes sitio\npara {STR_VAR_2}.",
  ["Aide_Text_GetEnoughMonsComeBackForItem"] = "¡Ah! Ya veo.\\pCuando tengas {STR_VAR_1} tipos, vuelve\na por {STR_VAR_2}.",
  ["Aide_Text_HaventCaughtEnoughMonsForItem"] = "Veamos...\n¡Oh! ¡Atrapaste solamente {STR_VAR_3} tipos\\lde POKéMON!\\pNecesitas {STR_VAR_1} tipos si quieres\n{STR_VAR_2}.",
  ["CableClub_Text_AdapterNotConnected"] = "El Conector inalámbrico de GBA\nno está bien conectado.",
  ["CableClub_Text_AwaitingLinkupBCancel"] = "Esperando conexión...\nBotón B: cancelar",
