  ["CableClub_Text_CantDoubleBattleWithXPlayers"] = "No se puede jugar al modo de\ncombate DOBLE con {STR_VAR_1} jugadores.",
  ["CableClub_Text_CantSingleBattleWithXPlayers"] = "No se puede jugar al modo de\ncombate INDIVIDUAL con {STR_VAR_1}\\ljugadores.",
