  ["Help_Text_WirelessAdapter"] = "El Conector inalámbrico de GBA.",
  ["OneIsland_KindleRoad_Text_AbigailRematchIntro"] = "Está empezando a dolerme la piel\npor las quemaduras.",
  ["OneIsland_KindleRoad_Text_BryceRematchIntro"] = "Cuando se está al aire libre,\ntodo sabe mucho mejor.",
  ["OneIsland_KindleRoad_Text_ClaireRematchIntro"] = "He vuelto a comer demasiado,\n¿luchamos para hacer algo\\lde ejercicio?",
  ["OneIsland_KindleRoad_Text_FinnRematchIntro"] = "El MT. ASCUAS hace una sombra\ngigante.",
  ["OneIsland_KindleRoad_Text_GarrettRematchIntro"] = "Tengo la sensación de que esta vez\nte voy a ganar.",
  ["OneIsland_KindleRoad_Text_HughRematchIntro"] = "¡Para luchar hay que llevar ropa\nadecuada! ¡Vaya pintas tienes!",
  ["OneIsland_KindleRoad_Text_KiaRematchIntro"] = "PÍA: ¡Mi hermano mayor y yo\nhacemos un equipo increíble!\\p¡Esta vez no perderemos!",
  ["OneIsland_KindleRoad_Text_MariaRematchIntro"] = "Hace un tiempo espléndido,\nno lo estropees.",
  ["OneIsland_KindleRoad_Text_MikRematchIntro"] = "FER: ¡Junto a PÍA no tengo miedo\nde nada!\\p¡Esta vez te vas a enterar!",
  ["OneIsland_KindleRoad_Text_SharonRematchIntro"] = "¿Me ayudas a entrenarme otra vez?",
  ["OneIsland_KindleRoad_Text_SheaRematchIntro"] = "Cada mañana, antes de desayunar,\nrodeo a nado la isla.\\l¡Lo hago hasta tres veces!",
  ["OneIsland_KindleRoad_Text_TanyaRematchIntro"] = "No me pierdo ni un día de\nentrenamiento.",
  ["OneIsland_KindleRoad_Text_TommyRematchIntro"] = "¡Eh, eh, un momento!\n¡Sé que he pescado algo grande!",
  ["OneIsland_TreasureBeach_Text_AmaraRematchIntro"] = "Se me pasa el tiempo volando\ncuando estoy disfrutando del agua,\\ldel vaivén de las olas...",
  ["PalletTown_Text_HmmIsThatRight"] = "Mmm...\nQué curioso...",
  ["PalletTown_Text_LookCopiedTrainerTipsSign"] = "¡Mira, mira!\\pHe copiado lo que ponía en uno\nde los carteles de PISTAS\\lENTRENADOR.",
  ["PalletTown_Text_OhLookLook"] = "¡Eh, mira, mira!",
  ["PalletTown_Text_PressStartToOpenMenu"] = "PISTAS ENTRENADOR\\p¡Pulsa START para abrir el MENÚ!",
  ["PalletTown_Text_PressStartToOpenMenuCopy"] = "PISTAS ENTRENADOR\\p¡Pulsa START para abrir el MENÚ!",
  ["PalletTown_Text_ReadItReadIt"] = "¡Mira lo que pone aquí, léelo!",
  ["PalletTown_Text_SignsAreUsefulArentThey"] = "Es básico leer lo que pone en los\ncarteles, ¿no te parece?",
  ["PokedexRating_Text_Complete"] = "¡Tu POKéDEX está completa!\n¡Enhorabuena!",
  ["PokedexRating_Text_HowIsPokedexComingAlong"] = "OAK: ¡Encantado de verte!\n¿Cómo va tu POKéDEX?\\p¡Déjame que le eche un vistazo!",
  ["PokedexRating_Text_LessThan10"] = "Te queda mucho por hacer.\\p¡Busca a los POKéMON en las zonas\nde hierba!",
  ["PokedexRating_Text_LessThan100"] = "¡Impresionante!\n¡Debe de haber sido muy difícil!",
  ["PokedexRating_Text_LessThan110"] = "¡Por fin tienes 100 especies!\n¡Se te da genial!",
  ["PokedexRating_Text_LessThan120"] = "¡Y has conseguido hasta transformar\na tus POKéMON! ¡Eres genial!",
  ["PokedexRating_Text_LessThan130"] = "¡Excelente! ¡Intercambia con tus\namigos y tendrás más!",
  ["PokedexRating_Text_LessThan140"] = "¡Impresionante!\n¡Eres muy profesional!",
  ["PokedexRating_Text_LessThan150"] = "¡No tengo nada más que decir!\n¡Ahora eres una eminencia!",
  ["PokedexRating_Text_LessThan20"] = "¡Estás en buen camino!\\p¡Pídele a uno de mis AYUDANTES\nla MO DESTELLO que le\\lhe dado para ti!",
  ["PokedexRating_Text_LessThan30"] = "¡Necesitas más POKéMON!\n¡Intenta capturar otras especies!",
  ["PokedexRating_Text_LessThan40"] = "¡Muy bien!\\p¡Pídele a uno de mis AYUDANTES\nun BUSCAOBJETOS que le\\lhe dado para ti!",
  ["PokedexRating_Text_LessThan50"] = "¡Tu POKéDEX va de maravilla!\\p¡Pídele a uno de mis AYUDANTES\nla MONEDA AMULETO que le\\lhe dado para ti!",
  ["PokedexRating_Text_LessThan60"] = "¡Ya has conseguido 50 especies!\\p¡Pídele a uno de mis AYUDANTES\nel REPARTIR EXP. que le he dado\\lpara ti!",
  ["PokedexRating_Text_LessThan70"] = "¡Oh!\n¡Lo estás haciendo genial!",
  ["PokedexRating_Text_LessThan80"] = "¡Excelente!\\p¡Ve a pescar algunos POKéMON\ndel mar!",
  ["PokedexRating_Text_LessThan90"] = "¡Magnífico!\nTe encanta coleccionar cosas, ¿eh?",
  ["PokedexRating_Text_LookForwardToFilledNationalDex"] = "¡Estoy deseando ver cómo completas\nla POKéDEX NACIONAL!",
  ["PokedexRating_Text_LoveSeeingYourPokedex"] = "OAK: ¡Hola!\\p¿Qué tal llevas la POKéDEX?\\pA ver...\\pLa verdad es que sé cómo es, pero\nme gusta verla de todas formas.\\pA ver, a ver...",
  ["PokedexRating_Text_NationalDexSeenXOwnedY"] = "A ver cómo llevas la POKéDEX\nNACIONAL:\\pPOKéMON avistados: {STR_VAR_1}\nPOKéMON atrapados: {STR_VAR_2}",
  ["PokedexRating_Text_ThankYouMadeDreamReality"] = "¡Gracias, {PLAYER}!\nGracias de verdad.\\l¡Has hecho mi sueño realidad!",
  ["PokedexRating_Text_Wroooaaarrr"] = "¡Guuuaaaaauuuuu!",
  ["PokedexRating_Text_YouveCompletedDex"] = "¡Por fin!\\p¡Ya has completado la POKéDEX!\\p¡Magnífico!\n¡De verdad, no era tarea fácil!",
  ["Pokedude_Text_BattlersTakeTurnsAttacking"] = "Se lucha por turnos. ¡Hay que\nintentar dejar sin PS al rival!",
  ["Pokedude_Text_BestIfTargetStatused"] = "Bueno, yo creo que es suficiente.\\pAunque, claro, lo ideal sería que\ntuviera algún problema de estado.\\pVamos, que sería más fácil si\nestuviera dormido o paralizado.",
  ["Pokedude_Text_ButterfreeDoubleResistsGrass"] = "BUTTERFREE es un POKéMON\ndel tipo BICHO-VOLADOR.\\pUn movimiento del tipo PLANTA...\\pHace la mitad de daño a los\nPOKéMON del tipo BICHO...\\pY también causa la mitad de daño\na los POKéMON del tipo VOLADOR.\\pVamos, que BUTTERFREE, al ser\ndel tipo BICHO-VOLADOR, sólo\\lrecibe una cuarta parte del daño.",
  ["Pokedude_Text_ButterfreeGoodAgainstOddish"] = "ODDISH es un POKéMON del tipo\nPLANTA-VENENO.\\pLos movimientos de los tipos\nVOLADOR o PSÍQUICO son\\lmuy eficaces contra él.\\pVamos, que le harán el doble\nde daño de lo habitual.\\p¡Bueno, vamos allá!",
  ["Pokedude_Text_CantDoubleUpOnStatus"] = "¡Así es mucho más sencillo atrapar\nal POKéMON!\\pAunque, claro, si se paraliza a un\nPOKéMON, ¡no se le podrá dormir!\\pVamos, que no se pueden causar\ndos problemas de estado a la vez.",
  ["Pokedude_Text_GrassEffectiveAgainstWater"] = "Vaya, mal asunto...\\pEl ataque ABSORBER que ha usado\nes un movimiento del tipo PLANTA.\\pY POLIWAG es un POKéMON\ndel tipo AGUA...\\pVamos, que ABSORBER es muy eficaz\ny causa el doble de daño.",
  ["Pokedude_Text_HealStatusRightAway"] = "Si un POKéMON tiene problemas de\nestado, hay que curarlo corriendo.",
  ["Pokedude_Text_LetMeThrowBall"] = "¡Bueno, vamos a lanzar una POKé\nBALL!",
  ["Pokedude_Text_LetsTryShiftingMons"] = "Con esta combinación, lo tenemos\ncrudo para ganar...\\p¡Vamos a cambiar de POKéMON!",
  ["Pokedude_Text_MyRattataFasterThanPidgey"] = "Se ve que mi RATTATA ha sido\nmás rápido que este PIDGEY.",
  ["Pokedude_Text_MyRattataWonGetsEXP"] = "Como mi RATTATA ha dejado sin PS\nal enemigo, ¡gana el combate!\\pTodos los POKéMON participantes\nen la lucha ganan puntos de EXP.\\pY cuando ganan suficientes puntos\nde EXP., pueden subir de nivel.\\pCon el aumento de nivel, los\nPOKéMON se hacen más fuertes.",
  ["Pokedude_Text_PickBestKindOfBall"] = "Antes de lanzar una POKé BALL,\nhay que tener en cuenta el estado\\ly el tipo del POKéMON.\\pAsí, se podrá elegir la BALL que\nva mejor.",
  ["Pokedude_Text_ShiftingUsesTurn"] = "Claro que al cambiar de POKéMON\nse usa un turno...\\p¡Ahora, le toca al enemigo!",
  ["Pokedude_Text_SpeedierBattlerGoesFirst"] = "POKéLOTODO: El más rápido atacará\nprimero.",
  ["Pokedude_Text_UhOhRattataPoisoned"] = "POKéLOTODO: Vaya fastidio...\nMi RATTATA se ha envenenado...\\pCuando un POKéMON se envenena,\nvaya, cuando lo envenenan,\\lva perdiendo PS poco a poco.",
  ["Pokedude_Text_UsingItemTakesTurn"] = "¡Pero si se usa un objeto en un\nPOKéMON, se usa también un turno!\\p¡Ahora, le toca al enemigo!",
  ["Pokedude_Text_WaterNotVeryEffectiveAgainstGrass"] = "POKéLOTODO: El movimiento BURBUJA\nes un ataque del tipo AGUA.\\pY nuestro objetivo, ODDISH, es un\nPOKéMON del tipo PLANTA-VENENO.\\pAsí que el tipo PLANTA absorberá\nel efecto del tipo AGUA.\\pVamos, que el movimiento no es\nmuy eficaz y causa la mitad\\lde daño.",
  ["Pokedude_Text_WeakenMonBeforeCatching"] = "POKéLOTODO: Para atrapar POKéMON,\nno hay que ponerse a tirar POKé\\lBALLS sin más.\\pPrimero hay que bajar sus PS todo\nlo que se pueda.",
  ["Pokedude_Text_YayWeManagedToWin"] = "¡Yupi!\n¡Hemos ganado!",
  ["Pokedude_Text_YeahWeWon"] = "¡Yupi!\n¡Hemos ganado!",
  ["PokemonJournal_Text_SpecialFeatureAgatha"] = "DIARIO POKéMON\\pÚltima hora sobre AGATHA,\nmiembro del ALTO MANDO.\\pSegún fuentes cercanas, AGATHA\ny el PROF. OAK estuvieron\\penfrentados durante su formación\ncomo ENTRENADORES.",
  ["PokemonJournal_Text_SpecialFeatureBlaine"] = "DIARIO POKéMON\\pÚltima hora sobre BLAINE, LÍDER\ndel GIMNASIO de CANELA.\\pSegún fuentes cercanas, BLAINE\nsólo se quita las gafas de sol\\lcuando contesta a preguntas.",
  ["PokemonJournal_Text_SpecialFeatureBrock"] = "DIARIO POKéMON\\pÚltima hora sobre BROCK, LÍDER\ndel GIMNASIO de PLATEADA.\\pSegún fuentes cercanas, BROCK\ncasi nunca se ríe, ¡pero una vez\\lque empieza, no para!",
  ["PokemonJournal_Text_SpecialFeatureBruno"] = "DIARIO POKéMON\\pÚltima hora sobre BRUNO,\nmiembro del ALTO MANDO.\\pSegún fuentes cercanas, BRUNO\nse unió al ALTO MANDO para luchar\\lcontra los mejores ENTRENADORES.",
  ["PokemonJournal_Text_SpecialFeatureDaisyOak"] = "Un DIARIO POKéMON de hace\nunos años...\\p¡Especial sobre el CONCURSO\ndel DIARIO POKéMON!\\p¡La campeona de la edición de\nprimavera del CONCURSO POKéMON\\les DALIA OAK, de PUEBLO PALETA!",
  ["PokemonJournal_Text_SpecialFeatureErika"] = "DIARIO POKéMON\\pÚltima hora sobre ERIKA, LÍDER\ndel GIMNASIO de AZULONA.\\pSegún fuentes cercanas, es fácil\nver a ERIKA echándose una siesta\\len el GIMNASIO de AZULONA.",
  ["PokemonJournal_Text_SpecialFeatureKoga"] = "DIARIO POKéMON\\pÚltima hora sobre KOGA, LÍDER\ndel GIMNASIO de FUCSIA.\\pSegún fuentes cercanas, KOGA\ntiene grandes conocimientos\\lde medicina.\\pIncluso elabora las medicinas\nque sus POKéMON necesitan.",
  ["PokemonJournal_Text_SpecialFeatureLance"] = "DIARIO POKéMON\\pÚltima hora sobre LANCE,\nmiembro del ALTO MANDO.\\pSegún fuentes cercanas, quien fundó\nel clan de los maestros del tipo\\lDRAGÓN fue el abuelo de LANCE.",
  ["PokemonJournal_Text_SpecialFeatureLorelei"] = "DIARIO POKéMON\\pÚltima hora sobre LORELEI,\nmiembro del ALTO MANDO.\\pSegún fuentes cercanas, LORELEI\nguarda un gran secreto.\\pLo que sí se conoce de ella es\nsu estilo de lucha elegante, único\\ly calculador.",
  ["PokemonJournal_Text_SpecialFeatureLtSurge"] = "DIARIO POKéMON\\pÚltima hora sobre LT. SURGE, LÍDER\ndel GIMNASIO de CARMÍN.\\pSegún fuentes cercanas, LT. SURGE\nera piloto cuando vivía en Estados\\lUnidos.\\pY se valía de la electricidad\ngenerada por sus POKéMON\\lpara poner en marcha su avión.",
  ["PokemonJournal_Text_SpecialFeatureMisty"] = "DIARIO POKéMON\\pÚltima hora sobre MISTY, LÍDER\ndel GIMNASIO de CELESTE.\\pSegún fuentes cercanas, MISTY\nadora a LORELEI, del ALTO MANDO.",
  ["PokemonJournal_Text_SpecialFeatureMrFuji"] = "DIARIO POKéMON\\pÚltima hora sobre el SR. FUJI,\nde la CASA POKéMON.\\pNota del editor: el tímido\nSR. FUJI no ha querido contestar\\la nuestras preguntas.\\pCon todo, hay que decir que es una\npersona muy querida en PUEBLO\\lLAVANDA.",
  ["PokemonJournal_Text_SpecialFeatureProfOak"] = "DIARIO POKéMON\\pÚltima hora sobre el PROF.\nOAK, el investigador de POKéMON.\\pSegún dicen, el PROF. OAK vive\ncon su nieta DALIA y {RIVAL}.",
  ["PokemonJournal_Text_SpecialFeatureSabrina"] = "DIARIO POKéMON\\pÚltima hora sobre SABRINA, LÍDER\ndel GIMNASIO de AZAFRÁN.\\pSegún fuentes cercanas, SABRINA\nse comunica en combate con sus\\lPOKéMON, sin necesidad de hablar.",
  ["Route10_Text_CarolRematchIntro"] = "Me está empezando a dar vueltas la\ncabeza. Llevo mucho escalando...",
  ["Route10_Text_ClarkRematchIntro"] = "¡A-a-a-achís!\n¡No puedo dejar de estornudar!",
  ["Route10_Text_HeidiRematchIntro"] = "He vuelto a ir al GIMNASIO\nPOKéMON.\\pPero he perdido, como siempre...",
  ["Route10_Text_HermanRematchIntro"] = "¡Hola!\n¿Te llegué a enseñar mis POKéMON?",
  ["Route10_Text_MarkRematchIntro"] = "Aquí estás otra vez...\n¿Eres como los POKéMANÍACOS?\\l¿Quieres ver mi colección?",
  ["Route10_Text_TrentRematchIntro"] = "¡Me encanta el aire de montaña!\n¡Es tan bueno! ¡Me encanta!",
  ["Route11_Text_BernieRematchIntro"] = "¡Cuidado con esos cables!",
  ["Route11_Text_BraxtonRematchIntro"] = "¡Eh, tú!\\p¡Cuidado!\n¡Estoy colocando unos cables!",
  ["Route11_Text_DarianRematchIntro"] = "Nunca he ganado...\\p¿Será mi destino?",
  ["Route11_Text_DaveRematchIntro"] = "¡Mis POKéMON ya deberían estar\nlistos! ¡Esta vez hay que ganar!",
  ["Route11_Text_DillonRematchIntro"] = "¡Soy un nuevo ENTRENADOR!\n¡Pero creo que no tengo problema\\lpara ganar!",
  ["Route11_Text_DirkRematchIntro"] = "¡Ja, ja, ja!\n¡No he perdido nunca!\\p¡Y si he perdido alguna vez,\nno me acuerdo!",
  ["Route11_Text_EddieRematchIntro"] = "¿Luchamos otra vez?\n¡Vamos allá, pero no hagas\\ltrampas!",
  ["Route11_Text_HugoRematchIntro"] = "¡Gana, pierde o empata!\n¡Pero lucha de nuevo!",
  ["Route11_Text_JasperRematchIntro"] = "¡Competir es lo más!\n¡Yo no me canso de competir!",
  ["Route11_Text_YasuRematchIntro"] = "¡Soy el mejor de mi clase!\n¡Me entreno día y noche!",
  ["Route12_Text_AndrewRematchIntro"] = "¿No sabes cómo pescar?\\p¡Te lo explicaré cuando acabe\ncontigo!",
  ["Route12_Text_ChipRematchIntro"] = "¡Aquí estás otra vez!\n¡Pescar requiere tiempo!",
  ["Route12_Text_ElliotRematchIntro"] = "A mí me encanta pescar, pero no\nes nada fácil que piquen, ¿sabes?",
  ["Route12_Text_GiaRematchIntro"] = "AGA: Oye, ARE, estoy aburrida\nde esperar...\\pSi ganamos, ¡me caso contigo!",
  ["Route12_Text_HankRematchIntro"] = "¡El PESCADOR LOCO contra alguien\nque no tiene idea sobre POKéMON!\\l¡Lucha, venga!",
  ["Route12_Text_JesRematchIntro"] = "ARE: Voy a ganar y a pedirle a\nAGA que se case conmigo.",
  ["Route12_Text_JustinRematchIntro"] = "Sigo sin PIEDRA LUNAR...\n¿Tienes tú una?",
  ["Route12_Text_LucaRematchIntro"] = "¡Soy un experto en electricidad!\\pPero de los POKéMON de agua\nsé poca cosa...",
  ["Route12_Text_NedRematchIntro"] = "¡Bien!\n¡Ha picado algo!\\l¡Esta vez seguro que es bueno!",
  ["Route13_Text_AlmaRematchIntro"] = "Me he gastado mis ahorros\ncomprando más CARBURANTE.",
  ["Route13_Text_GwenRematchIntro"] = "Mis simpáticos POKéMON quieren\nvolver a verte.",
  ["Route13_Text_JaredRematchIntro"] = "¿Qué miras?",
  ["Route13_Text_LolaRematchIntro"] = "Has vuelto...\\pPor supuesto que lucharé\notra vez contigo.",
  ["Route13_Text_PerryRematchIntro"] = "¡Esta vez no pienso perder!\n¡El viento sopla en mi dirección!",
  ["Route13_Text_RobertRematchIntro"] = "¡Me encantan los pájaros POKéMON!",
  ["Route13_Text_SebastianRematchIntro"] = "¡Mis pájaros POKéMON se acuerdan\nde ti!",
  ["Route13_Text_SheilaRematchIntro"] = "¿No te acuerdas de que luchamos\nen otra ocasión?",
  ["Route13_Text_SusieRematchIntro"] = "Quiero ser la mejor ENTRENADORA\nsiendo todavía pequeña.",
  ["Route13_Text_ValerieRematchIntro"] = "¡Guau!\n¡Qué chulas son tus MEDALLAS!",
  ["Route14_Text_BeckRematchIntro"] = "¿Usas MT con tus POKéMON?\nTenerlas en la MOCHILA sin más\\lno sirve para nada.",
  ["Route14_Text_BennyRematchIntro"] = "¡No me apetece luchar,\npero lo haré!",
  ["Route14_Text_CarterRematchIntro"] = "He usado mis MT para enseñarles\nbuenos movimientos a mis POKéMON.",
  ["Route14_Text_DonaldRematchIntro"] = "¿Llegaste a oír hablar de los\nmisteriosos seres alados?",
  ["Route14_Text_GeraldRematchIntro"] = "¡Nos gusta pedalear por aquí\nporque hay mucho espacio!",
  ["Route14_Text_IsaacRematchIntro"] = "Aquí estás otra vez, ¿eh?\n¡Bueno, así pasaré el rato!",
  ["Route14_Text_JanRematchIntro"] = "TEA: LENA, ¡vamos allá!\n¡Tenemos que ganar!",
  ["Route14_Text_KiriRematchIntro"] = "LENA: TEA, a ver si ganamos.",
  ["Route14_Text_LukasRematchIntro"] = "¡Eh, me acuerdo de ti!\\p¡Venga, venga!\n¡Vamos, vamos! ¡Adelante!",
  ["Route14_Text_MalikRematchIntro"] = "¿Quieres pelear con tus POKéMON?\n¡Pues vale, vamos allá!",
  ["Route14_Text_MarlonRematchIntro"] = "¿Has enseñado a VOLAR a tus\npájaros POKéMON?\\pDeberías hacerlo y disfrutar de\nla maravillosa vista.",
  ["Route14_Text_MitchRematchIntro"] = "Mis pájaros POKéMON deberían\nluchar bien esta vez.",
  ["Route15_Text_AlexRematchIntro"] = "¡Mira, colega, si pierdes contra\nmí, todo tu dinero será mío!",
  ["Route15_Text_BeckyRematchIntro"] = "¡Creo que puedo contigo!\n¡Voy a intentar vencerte!",
  ["Route15_Text_CeliaRematchIntro"] = "¿Qué mola?\n¡Cambiar POKéMON, claro!",
  ["Route15_Text_ChesterRematchIntro"] = "Mis pájaros están temblando.\n¡Ya te conocen!",
  ["Route15_Text_EdwinRematchIntro"] = "Cuando silbo, acuden varios\npájaros POKéMON.\\p¡Son monísimos!",
  ["Route15_Text_ErnestRematchIntro"] = "¡Oye! ¡Ven aquí!\n¡Mira esto!",
  ["Route15_Text_GraceRematchIntro"] = "¡Oh!\n¡Mira qué encanto!\\l¡Anda, yo a ti te conozco!",
  ["Route15_Text_KindraRematchIntro"] = "¡Déjame probar los POKéMON\nque me han enviado!",
  ["Route15_Text_MyaRematchIntro"] = "TINA: ¡Volvemos a vernos!\\p¿Luchamos para que aprenda\nmi hermano?",
  ["Route15_Text_OliviaRematchIntro"] = "¡Cuido POKéMON porque sigo\nviviendo sola!",
  ["Route15_Text_RonRematchIntro"] = "TIN: Mi hermana es la más fuerte.",
  ["Route15_Text_YazminRematchIntro"] = "¿Quieres jugar con mis POKéMON\notra vez?",
  ["Route16_Text_CamronRematchIntro"] = "¡Tengo hambre y sigo sin estar\nde humor!",
  ["Route16_Text_HideoRematchIntro"] = "¡Oye! ¡Me has golpeado!\n¡Ahora tendrás que luchar conmigo!",
  ["Route16_Text_JedRematchIntro"] = "JOEL: ¿Vienes para comprobar que\nnuestro amor no conoce límites?",
  ["Route16_Text_KojiRematchIntro"] = "¡Bonita BICI!\n¡Dámela ahora mismo!",
  ["Route16_Text_LaoRematchIntro"] = "¿Qué quieres?",
  ["Route16_Text_LeaRematchIntro"] = "LIZ: ¡A veces, pienso en todo\nlo que nos queremos y se me pone\\lla carne de gallina!",
  ["Route16_Text_LukeRematchIntro"] = "¡Baja de ahí y lucha, enclenque!\n¡Te vas a enterar!",
  ["Route16_Text_RubenRematchIntro"] = "¡Eh, vamos a echar otro rato!",
  ["Route17_Text_BillyRematchIntro"] = "¡Somos los MOTORISTAS!\n¡Las estrellas de la autopista!",
  ["Route17_Text_CoreyRematchIntro"] = "¡Sé rebelde!",
  ["Route17_Text_IsaiahRematchIntro"] = "¿Y tú qué quieres?",
  ["Route17_Text_JamalRematchIntro"] = "¡Necesito un poco de ejercicio\ny bajar peso!",
  ["Route17_Text_JaxonRematchIntro"] = "¡Tienes una BICI muy guay!\n¿Cómo se conduce?",
  ["Route17_Text_NikolasRematchIntro"] = "Mis VOLTORB van a darte\nun calambrazo.",
  ["Route17_Text_RaulRematchIntro"] = "¡Ya te dije que no compensaba\nluchar con niños!",
  ["Route17_Text_VirgilRematchIntro"] = "¿Qué vas, de paseo?",
  ["Route17_Text_WilliamRematchIntro"] = "¡Lárgate!\n¡Estoy agotado!",
  ["Route17_Text_ZeekRematchIntro"] = "¡Mi POKéMON no evoluciona!\nNo acabo de entender por qué.",
  ["Route18_Text_JacobRematchIntro"] = "¡Es mi césped!\n¡Fuera de aquí!\\p¡No quiero volver a verte por\naquí!",
  ["Route18_Text_RamiroRematchIntro"] = "¡Cucu, cucu! ¿Ha mejorado\nel reclamo de mi pájaro?",
  ["Route18_Text_WiltonRematchIntro"] = "Compruebo siempre las zonas de\nhierba en busca de nuevos POKéMON.\\pPero no siempre encuentro...",
  ["Route19_Text_AliceRematchIntro"] = "¡Nadar es genial! ¡Pero no me\ngusta quemarme al sol!",
  ["Route19_Text_AnyaRematchIntro"] = "¡Me encanta el POKéMON con\nel que estás haciendo SURF.\\p¿Me lo darás si gano?",
  ["Route19_Text_AxleRematchIntro"] = "¡Estas aguas son traicioneras!\n¡No deberías volver por aquí!",
  ["Route19_Text_ConnieRematchIntro"] = "He venido nadando hasta aquí,\npero ya me he cansado.\\p¿De verdad tenemos que luchar\notra vez?",
  ["Route19_Text_DavidRematchIntro"] = "¡He buceado en busca de POKéMON,\npero sigo sin ver nada!",
  ["Route19_Text_DouglasRematchIntro"] = "¿Qué hay más allá del horizonte?\n¿Lo sabes?",
  ["Route19_Text_LiaRematchIntro"] = "CATI: Ya sabes que mi hermano\nacaba de hacerse ENTRENADOR.\\pVamos a luchar para que mejore\nsu técnica, ¿vale?",
  ["Route19_Text_LucRematchIntro"] = "TEC: Mi hermana mayor me ha\nenseñado mucho sobre POKéMON.\\p¿Soy mejor ahora?",
  ["Route19_Text_MatthewRematchIntro"] = "¡Me gusta nadar!\nSeguro que a ti también.",
  ["Route19_Text_ReeceRematchIntro"] = "¡Alto!\n¡Oye, que te va a dar algo!",
  ["Route19_Text_RichardRematchIntro"] = "Estaba a punto de darme un baño.",
  ["Route19_Text_TonyRematchIntro"] = "¡Miro al mar para olvidar!\\pQuiero olvidarme de cuando perdí\ncontigo.",
  ["Route20_Text_BarryRematchIntro"] = "El agua es poco profunda aquí.\nHay mucha gente nadando.",
  ["Route20_Text_DarrinRematchIntro"] = "¿Por qué te has subido a un\nPOKéMON? ¿Aún no sabes nadar?",
  ["Route20_Text_DeanRematchIntro"] = "¡Mira que cuerpazo tengo!\\p¡Estoy mejor que antes!",
  ["Route20_Text_IreneRematchIntro"] = "¿Tú también estabas de vacaciones?",
  ["Route20_Text_MelissaRematchIntro"] = "En ISLA CANELA, al oeste, hay\nun LABORATORIO POKéMON.\\pMi papi trabaja allí.",
  ["Route20_Text_MissyRematchIntro"] = "Vine nadando desde ISLA\nCANELA. Fue agotador.",
  ["Route20_Text_NoraRematchIntro"] = "¡Mi novio me dio unas perlas\nmuy grandes!\\p¡Y ahora están más grandes aún!",
  ["Route20_Text_RogerRematchIntro"] = "¡He venido sobre uno de mis\npájaros POKéMON!",
  ["Route20_Text_ShirleyRematchIntro"] = "¿Te da envidia que esté de\nvacaciones en las ISLAS ESPUMA?",
  ["Route20_Text_TiffanyRematchIntro"] = "¡Me gusta flotar en el agua\nrodeada de peces!",
  ["Route21_North_Text_IanRematchIntro"] = "IGOR: Mi hermana es un pelín vaga,\n¡pero si hay que luchar, hay que\\lluchar!",
  ["Route21_North_Text_LilRematchIntro"] = "ÍA: ¿Cómo, que quieres luchar otra\nvez? IGOR, ¿cómo lo ves?",
  ["Route21_North_Text_RonaldRematchIntro"] = "¿Quieres saber si los peces pican?",
  ["Route21_North_Text_SpencerRematchIntro"] = "¡El mar limpia mi cuerpo y mi\nalma!",
  ["Route21_North_Text_WadeRematchIntro"] = "¡Tengo una gran red!\n¿Quieres probarla otra vez?",
  ["Route21_South_Text_ClaudeRematchIntro"] = "¡Eh!\n¡Siempre asustas a los peces!",
  ["Route21_South_Text_JackRematchIntro"] = "¡He conseguido a mi POKéMON\nen el mar, y aquí lo entreno!",
  ["Route21_South_Text_JeromeRematchIntro"] = "¡Ahora estoy en otro encuentro\nde triatlón!",
  ["Route21_South_Text_NolanRematchIntro"] = "¡Quédate conmigo hasta que lo\nconsiga!",
  ["Route21_South_Text_RolandRematchIntro"] = "¡Ah!\n¡Siente el sol y el viento!",
  ["Route24_Text_AliRematchIntro"] = "Aunque perdí cuando luchamos,\nestuvo guay, ¿verdad?",
  ["Route24_Text_CaleRematchIntro"] = "Éste es el PUENTE PEPITA.\\pYa nos has machacado a todos,\nasí que ya te puedes marchar...\\pAunque... no me importaría\nvolver a enfrentarme a ti.",
  ["Route24_Text_EthanRematchIntro"] = "¡Muy bien, voy a acabar contigo!",
  ["Route24_Text_ReliRematchIntro"] = "Siempre estás de aquí para allá...\n¿No te cansas?",
  ["Route24_Text_ShaneRematchIntro"] = "¡Vi tu hazaña desde la hierba!",
  ["Route24_Text_TimmyRematchIntro"] = "Se ve que te encanta venir\nal PUENTE PEPITA.",
  ["Route25_Text_ChadRematchIntro"] = "¡Sabía que tendría que luchar\ncontigo otra vez!",
  ["Route25_Text_DanRematchIntro"] = "¡Mi padre me llevó a una gran\nfiesta en el S.S. ANNE, en\\lCIUDAD CARMÍN!",
  ["Route25_Text_FlintRematchIntro"] = "Soy un buen chico.\n¡Y tengo novia!\\p¡Verás cómo se queda cuando\nme vea luchar esta vez!",
  ["Route25_Text_FranklinRematchIntro"] = "¡Acabo de bajar del MT. MOON,\npero estoy listo!",
  ["Route25_Text_HaleyRematchIntro"] = "Mi amigo tiene unos POKéMON\nmuy monos. ¡Qué envidia!",
  ["Route25_Text_JoeyRematchIntro"] = "¡No pienso perder!",
  ["Route25_Text_KelseyRematchIntro"] = "¡Hola!\n¡Mi chico es genial!\\l¡Y hoy me encuentro en forma!",
  ["Route25_Text_NobRematchIntro"] = "¡Hay un POKéMANÍACO viviendo\nen el cabo!\\p¿Has visto la colección que tiene?",
  ["Route25_Text_WayneRematchIntro"] = "¿Vas a ver a BILL otra vez?\n¡Pues luchemos primero!",
  ["Route3_Text_BenRematchIntro"] = "¡Hola!\n¡Me gustan los pantalones cortos!\\p¡Son muy cómodos!",
  ["Route3_Text_CalvinRematchIntro"] = "¡Oye!\n¡No llevas pantalón corto!",
  ["Route3_Text_ColtonRematchIntro"] = "¡Nos vimos en el BOSQUE VERDE!",
  ["Route3_Text_GregRematchIntro"] = "¿Entrenas POKéMON?\n¡Pues luchemos!",
  ["Route3_Text_JamesRematchIntro"] = "Lucharé contigo junto a los\nPOKéMON que yo mismo he criado.",
  ["Route3_Text_JaniceRematchIntro"] = "Estabas mirándome ¿verdad?",
  ["Route3_Text_RobinRematchIntro"] = "¡Eh!\n¡Me has empujado!",
  ["Route3_Text_SallyRematchIntro"] = "¡Esa mirada tuya fue de lo más\nmisteriosa!",
  ["Route4_Text_CrissyRematchIntro"] = "A mí me encanta buscar POKéMON\nhongo en el MT. MOON.",
  ["Route6_Text_ElijahRematchIntro"] = "Eh, ¡qué de tiempo!\n¿Eres más fuerte?",
  ["Route6_Text_IsabelleRematchIntro"] = "¿Yo?\nPues vale. ¡Vamos!",
  ["Route6_Text_JeffRematchIntro"] = "¿Qué? ¿Qué quieres, luchar\nconmigo de nuevo?",
  ["Route6_Text_KeigoRematchIntro"] = "Estoy intentando encontrar un buen\nejemplar, que no sea un POKéMON\\lBICHO, pero...",
  ["Route6_Text_NancyRematchIntro"] = "Perdona, ¿no ves que es una\nconversación privada?\\pPues ¿qué haces con la antena\npuesta?",
  ["Route6_Text_RickyRematchIntro"] = "¡Tu eres la pesadilla que nos\ndio la paliza!",
  ["Route8_Text_AidanRematchIntro"] = "Se te dan bien los POKéMON, pero\n¿qué tal en química?",
  ["Route8_Text_AndreaRematchIntro"] = "¡MEOWTH y PERSIAN son ideales,\nideales totales, meow, meow, meow!",
  ["Route8_Text_AnneRematchIntro"] = "LIN: ¡Ya somos mucho más fuertes!",
  ["Route8_Text_EliRematchIntro"] = "TITA: ¡Ahora somos más fuertes!",
  ["Route8_Text_GlennRematchIntro"] = "¡Necesitas una buena estrategia!\\p¿Te queda claro?",
  ["Route8_Text_JarenRematchIntro"] = "Bueno, esta vez no me voy\na andar con tonterías.",
  ["Route8_Text_JuliaRematchIntro"] = "¿Qué POKéMON es mono, redondo\ny blando?\\pLo sabes, ¿no?",
  ["Route8_Text_LeslieRematchIntro"] = "¡Me gusta el colegio y los\nPOKéMON!",
  ["Route8_Text_MeganRematchIntro"] = "Debemos de dar una imagen algo\ntonta, pero ¡lo importante es que\\lyo quiero luchar!",
  ["Route8_Text_PaigeRematchIntro"] = "Tengo muchos NIDORAN.\nNo quiero que evolucionen, pero...",
  ["Route8_Text_RicardoRematchIntro"] = "¡Mi bici sigue yendo como\nuna moto!",
  ["Route8_Text_RichRematchIntro"] = "¡Soy un jugador errante!\n¡Y voy a ganar!",
  ["Route8_Text_StanRematchIntro"] = "¡Muy bien!\n¡Luchemos otra vez!",
  ["Route9_Text_AlanRematchIntro"] = "¡Esta vez gano yo!",
  ["Route9_Text_AliciaRematchIntro"] = "¿Vamos a luchar de nuevo?\n¡Pues esta vez, olvídate!",
  ["Route9_Text_BrentRematchIntro"] = "Cada día me levanto temprano para\nentrenar a mis POKéMON capullo.",
  ["Route9_Text_BriceRematchIntro"] = "¡Jaja! ¡A ver lo fuerte que estás!",
  ["Route9_Text_CaitlinRematchIntro"] = "¡No te andes con contemplaciones!\n¡Hay que ir a por todas!",
  ["Route9_Text_ChrisRematchIntro"] = "Tú eras quien tenía esos POKéMON\ntan bonitos...",
  ["Route9_Text_ConnerRematchIntro"] = "¡Adelante de nuevo, mis geniales\nPOKéMON BICHO!",
  ["Route9_Text_DrewRematchIntro"] = "Quiero tomar el TÚNEL ROCA\npara ir a LAVANDA.\\p¡Pero cada dos por tres se cruza\nalguien en mi camino!...",
  ["Route9_Text_JeremyRematchIntro"] = "¡Qué bien! ¡Me estaba aburriendo\notra vez!",
  ["STRINGID_AARGHALMOSTHADIT"] = "¡Qué pena!\n¡Te faltó poco!",
  ["STRINGID_ABOOSTED"] = " adicionales",
  ["STRINGID_ANDELLIPSIS"] = "Y...\\p",
  ["STRINGID_ATTACKERCANTESCAPE"] = "¡{B_ATK_NAME_WITH_PREFIX}\nno puede escapar!",
  ["STRINGID_ATTACKERFAINTED"] = "¡{B_ATK_NAME_WITH_PREFIX}\nse debilitó!\\p",
  ["STRINGID_ATTACKERSSTATFELL"] = "¡{B_BUFF1} de {B_ATK_NAME_WITH_PREFIX}\n{B_BUFF2}!",
  ["STRINGID_ATTACKERSSTATROSE"] = "¡{B_BUFF1} de {B_ATK_NAME_WITH_PREFIX}\n{B_BUFF2}!",
  ["STRINGID_ATTACKMISSED"] = "¡El ataque de\n{B_ATK_NAME_WITH_PREFIX} falló!",
  ["STRINGID_AVOIDEDDAMAGE"] = "¡{B_DEF_NAME_WITH_PREFIX} se\nprotegió con {B_DEF_ABILITY}!",
  ["STRINGID_BELLCHIMED"] = "¡Ha repicado una campana!",
  ["STRINGID_BOXISFULL"] = "¡Las CAJAS están llenas!\n¡No puedes atrapar ninguno más!\\p",
  ["STRINGID_BUTITFAILED"] = "¡Pero falló!",
  ["STRINGID_BUTNOEFFECT"] = "¡Pero no surtió efecto!",
  ["STRINGID_BUTNOPPLEFT"] = "¡Pero no quedan PP para\neste movimiento!",
  ["STRINGID_BUTNOTHINGHAPPENED"] = "¡Pero no tuvo ningún efecto!",
  ["STRINGID_CANTESCAPE"] = "¡No puedes huir!\\p",
  ["STRINGID_CANTESCAPE2"] = "¡No puedes huir!\\p",
  ["STRINGID_COINSSCATTERED"] = "¡Hay monedas por todas partes!",
  ["STRINGID_CRITICALHIT"] = "¡Un golpe crítico!",
  ["STRINGID_DEFENDERSSTATFELL"] = "¡{B_BUFF1} de {B_DEF_NAME_WITH_PREFIX}\n{B_BUFF2}!",
  ["STRINGID_DEFENDERSSTATROSE"] = "¡{B_BUFF1} de {B_DEF_NAME_WITH_PREFIX}\n{B_BUFF2}!",
  ["STRINGID_DIDNOTLEARNMOVE"] = "{B_BUFF1} no aprendió\n{B_BUFF2}.\\p",
  ["STRINGID_DONTBEATHIEF"] = "¡Robar está mal!",
  ["STRINGID_DOWNPOURCONTINUES"] = "El chaparrón continúa...",
  ["STRINGID_DOWNPOURSTARTED"] = "¡Comenzó a caer un chaparrón!",
  ["STRINGID_ELECTRICITYWEAKENED"] = "¡Se han debilitado los\nataques ELÉCTRICOS!",
  ["STRINGID_ENEMYABOUTTOSWITCHPKMN"] = "{B_BUFF2} será el próximo POKéMON \nde {B_TRAINER1_CLASS} {B_TRAINER1_NAME}.\\p{B_PLAYER_NAME}, ¿quieres \ncambiar de POKéMON?",
  ["STRINGID_FAILEDTOSPITUP"] = "¡Pero no consiguió \nESCUPIR energía!",
  ["STRINGID_FAILEDTOSWALLOW"] = "¡Pero no consiguió \nTRAGAR energía!",
  ["STRINGID_FAINTINTHREE"] = "¡Los POKéMON de ambas partes se\ndebilitarán dentro de 3 turnos!",
  ["STRINGID_FIREWEAKENED"] = "¡Se han debilitado los\nataques de FUEGO!",
  ["STRINGID_FOESTOPPEDWORKING"] = "¡{B_BUFF1} no funciona\nen el equipo rival!",
  ["STRINGID_FORXCOMMAYZ"] = "¡{B_SCR_ACTIVE_NAME_WITH_PREFIX} encuentra\n{B_LAST_ITEM} {B_BUFF1}",
