  ["STRINGID_YOUTHROWABALLNOWRIGHT"] = "Ahora debo lanzar una BALL, ¿no?\n¡Intentaré hacerlo lo mejor posible!",
  ["SafariZone_Text_ExcuseMeYourPCBoxIsFull"] = "Lo siento, pero todas las CAJAS\nde tu PC están llenas.",
  ["SafariZone_Text_OutOfBalls"] = "AVISO: ¡Ding-dong!\\pTe has quedado sin SAFARI BALLS.\\pAVISO: ¡Tu JUEGO de SAFARI\nse ha terminado!",
  ["SafariZone_Text_TimesUp"] = "AVISO: ¡Ding-dong!\\p¡Se acabó el tiempo!\\pAVISO: ¡Tu JUEGO de SAFARI\nse ha terminado!",
  ["SafariZone_Text_WouldYouLikeToExit"] = "¿Quieres salir de la ZONA del\nSAFARI ahora mismo?",
  ["SevenIsland_SevaultCanyon_Entrance_Text_EveRematchIntro"] = "ELE: RUS y yo queremos luchar\nde nuevo contigo.",
  ["SevenIsland_SevaultCanyon_Entrance_Text_JonRematchIntro"] = "RUS: Cuando estoy con ELE,\ncreo que no voy a perder nunca.\\lAhora lo veremos.",
  ["SevenIsland_SevaultCanyon_Entrance_Text_MadelineRematchIntro"] = "¡No perdono a quien se pasa con\nlos POKéMON!",
  ["SevenIsland_SevaultCanyon_Entrance_Text_MasonRematchIntro"] = "¡Hola, cara de bola!\n¿Tú no eras de mi club de fans?",
  ["SevenIsland_SevaultCanyon_Entrance_Text_MiahRematchIntro"] = "¡Voy a acabar contigo en un abrir\ny cerrar de ojos!\\p¡No te creas que por volver\nvas a ganarme!",
  ["SevenIsland_SevaultCanyon_Entrance_Text_NicolasRematchIntro"] = "Esta isla tiene una extensión muy\nparticular, no es fácil patrullar.",
  ["SevenIsland_SevaultCanyon_Text_CyndyRematchIntro"] = "Vamos a luchar de nuevo.\n¡Estoy realmente en forma!",
  ["SevenIsland_SevaultCanyon_Text_EvanRematchIntro"] = "Da igual que tengas los POKéMON\nmás fuertes...\\p¡Lo importante es saber cómo\ntratarlos!",
  ["SevenIsland_SevaultCanyon_Text_JacksonRematchIntro"] = "Yo protejo el medio ambiente\ny él me protege a mí.",
  ["SevenIsland_SevaultCanyon_Text_KatelynRematchIntro"] = "La última vez que nos vimos,\nllevabas también esos zapatos\\ltan llamativos.",
  ["SevenIsland_SevaultCanyon_Text_LeroyRematchIntro"] = "¡Debes de ser más fuerte!\n¡Vamos a luchar, anda!",
  ["SevenIsland_SevaultCanyon_Text_LexRematchIntro"] = "LINO: Mi adorada ABA, ¡vamos\na ganar!",
  ["SevenIsland_SevaultCanyon_Text_MichelleRematchIntro"] = "He recibido la mejor educación\npara tener la fuerza que tengo.\\p¡No pienso perder esta vez!\n¡Ni en broma!",
  ["SevenIsland_SevaultCanyon_Text_NyaRematchIntro"] = "ABA: No defraudaré a mi maestro\nLINO. ¡Tenemos que ganar!",
  ["SevenIsland_TanobyRuins_Text_BenjaminRematchIntro"] = "Dicen que aquí dentro duerme\nun mítico POKéMON.",
  ["SevenIsland_TanobyRuins_Text_BrandonRematchIntro"] = "¿Has descubierto algo de esta\ncámara de piedra?",
  ["SevenIsland_TanobyRuins_Text_CliffordRematchIntro"] = "Hoy, como complemento a la clase,\nhemos venido a visitar la cámara\\lotra vez.",
  ["SevenIsland_TanobyRuins_Text_EdnaRematchIntro"] = "Mi profe me está enseñando\nnuevas técnicas de pintura.",
  ["SevenIsland_TrainerTower_Text_DarioRematchIntro"] = "He notado que te acercabas.",
  ["SevenIsland_TrainerTower_Text_RodetteRematchIntro"] = "En alguna parte de esta isla,\nhay extraños POKéMON durmiendo.",
  ["SixIsland_GreenPath_Text_JaclynRematchIntro"] = "¿Mmm?...\\pMe pareció haber elegido mi casa\ncon TELETRANSPORTE, pero\\lsiempre acabo en el mismo sitio.",
  ["SixIsland_OutcastIsland_Text_AvaRematchIntro"] = "ALI: ¡Vamos a echarnos otro\ncombate disfrutando de la brisa\\lmarina!",
  ["SixIsland_OutcastIsland_Text_GebRematchIntro"] = "ROS: Mi hermanita y yo somos\nmás fuertes que antes.",
  ["SixIsland_OutcastIsland_Text_MymoRematchIntro"] = "Ufff... Ufff...\\pVengo nadando otra vez desde\nel PUERTO de ISLA EXTA sin parar.",
  ["SixIsland_OutcastIsland_Text_NicoleRematchIntro"] = "Siempre apareces cuando estoy\ndándome un baño.",
  ["SixIsland_OutcastIsland_Text_TylorRematchIntro"] = "Sigo sin tener suerte...\n¡A ver si luchando contigo entro\\len una buena racha!",
  ["SixIsland_RuinValley_Text_DarylRematchIntro"] = "¿Luchar contigo otra vez?\n¡Ahora mismo!",
  ["SixIsland_RuinValley_Text_FosterRematchIntro"] = "Yo a ti te conozco...\n¿Qué te trae de nuevo hasta aquí?",
  ["SixIsland_RuinValley_Text_HectorRematchIntro"] = "Yo me conozco bien toda esta\nzona.",
  ["SixIsland_RuinValley_Text_LarryRematchIntro"] = "Dicen que hay misteriosas piedras\nen esta isla.\\p¿Has descubierto algo desde\nla última vez que nos vimos?",
  ["SixIsland_RuinValley_Text_StanlyRematchIntro"] = "Creo que en este mundo quedan\nmisterios por resolver.",
  ["SixIsland_WaterPath_Text_DeniseRematchIntro"] = "Ufff...\nMi chico está liado otra vez...",
  ["SixIsland_WaterPath_Text_EarlRematchIntro"] = "Oye, dime dónde están las\nmontañas de esta zona, anda.",
  ["SixIsland_WaterPath_Text_EdwardRematchIntro"] = "Estoy practicando en secreto\notra vez.",
  ["SixIsland_WaterPath_Text_MiaRematchIntro"] = "MÍA: ¡Queridos POKéMON!\n¡Vamos a luchar otra vez!",
  ["SixIsland_WaterPath_Text_MiuRematchIntro"] = "MARU: ¡Queridos POKéMON!\n¡Vamos a jugar otra vez!",
  ["SixIsland_WaterPath_Text_RoseRematchIntro"] = "He llegado otra vez hasta aquí\ndejándome llevar por un agradable\\laroma.",
  ["SixIsland_WaterPath_Text_SamirRematchIntro"] = "¿Perdona? ¿Que no te gusta\nla gente que hace natación\\lcomo yo?\\p¡No fastidies!\n¡Vamos a luchar otra vez!",
  ["Text_ATownMap"] = "MAPA",
