  ["Text_AccessedProfOaksPC"] = "Accedes al PC del PROF. OAK.\\pAccedes al Sistema de Evaluación\nde la POKéDEX.",
  ["Text_AccessedSomeonesPC"] = "Accedió al PC de alguien.",
  ["Text_AdapterNotConnectedMinigame"] = "El Conector inalámbrico de GBA\nno está conectado.\\p¡Vuelve cuando lo tengas!",
  ["Text_AdvertisingPoster"] = "Es un póster promocional\ncon todo tipo de productos.",
