  ["Text_BlinkingLights"] = "Cuántas lucecitas de colores\nque se encienden y se apagan...",
  ["Text_Blueprints"] = "Y este plano... ¿de dónde será?\\pTiene gráficos y anotaciones\nrarísimas.",
  ["Text_Bookshelf"] = "¡Totalmente lleno de libros sobre\nlos POKéMON!",
