  ["Text_DiveCantBeUsedHere"] = "Hay algún obstáculo en la\nsuperficie.\\lNo se puede usar BUCEO.",
  ["Text_DodrioBerryPickingInfo"] = "“DODRIO A POR BAYAS”\\pDile a DODRIO que pille las BAYAS\nque pueda con los tres picos que\\ltiene.\\pPulsa derecha, izquierda o arriba\nen el {PLUS} Panel de Control para\\lque se mueva.\\pPara poder jugar a este juego,\nhay que tener un DODRIO.",
  ["Text_DontBeLikeThat"] = "Venga, anda, enséñame tu perfil...",
  ["Text_Dresser"] = "Qué mueble más estupendo...\nAquí caben un montón de cosas.",
  ["Text_DugUpItemFromGround"] = "{PLAYER} encontró una unidad\nde {STR_VAR_2} bajo la tierra.",
  ["Text_EnterWhichPokemon"] = "¿Con qué POKéMON quieres\nparticipar?",
  ["Text_ExplainProfile"] = "El perfil puede hacerse con\npalabras o frases.\\pHay muchas palabras y frases\npara elegir, y están divididas\\lpor grupos.\\pSelecciona primero un grupo\ny después el elemento que quieras.\\pEs mucho más fácil de lo que\nparece. Inténtalo, anda.",
  ["Text_FillOutQuestionnaire"] = "Hay un cuestionario.\n¿Quieres rellenarlo?",
  ["Text_FirstShouldRestoreMonsHealth"] = "Primero, deberías devolverles\nla forma a tus POKéMON.",
  ["Text_Food"] = "Seguramente está lleno de cosas\nde lo más apetecibles.",
  ["Text_FoundOneItem"] = "¡{PLAYER} encontró {STR_VAR_2}!",
  ["Text_FoundXCoins"] = "¡{PLAYER} encontró\n{STR_VAR_1} {STR_VAR_2}!",
  ["Text_FoundXItems"] = "{PLAYER} encontró estas unidades\nde {STR_VAR_2}: ¡{STR_VAR_1}!",
