  ["Text_GiveNicknameToThisMon"] = "¿Quieres darle un mote a tu\n{STR_VAR_1}?",
  ["Text_Gyaoo"] = "¡Artic!",
  ["Text_HadQuiteAnExperienceTakeRest"] = "MAMÁ: ¡{PLAYER}!\n¡Hola, cielo!\\p¡Tienes cara de haber aprendido\nbastante!\\p¡Descansa un poco, criatura!",
  ["Text_HandedOverItem"] = "¡{PLAYER} entregó\n{STR_VAR_1}!",
  ["Text_HavePokedexRated"] = "¿Quieres evaluar tu POKéDEX?",
  ["Text_HavingDiscountSaleToday"] = "¡Hola!\\p¡Hoy tenemos rebajas!",
  ["Text_HeardThatBefore"] = "Eso ya lo he oído antes...\\pMi primo, que vive lejos de aquí,\nlo decía con frecuencia, creo.",
  ["Text_HiWeMeetAgain"] = "¡Hola otra vez!",
  ["Text_IdLoveToHearYourProfile"] = "Hola, me alegro de verte.\\pEh, he dicho hola...\nQué borde... ya podrías\\lcontestar.\\pVenga, cuéntame algo, anda.\\p¡Dime al menos cuál es tu perfil!",
  ["Text_ImpressiveMachine"] = "No sé qué será esta máquina,\npero es impresionante.",
  ["Text_Indigo_HighestAuthority"] = "MESETA AÑIL\\pLa máxima autoridad POKéMON\ndel CG de la LIGA POKéMON.",
  ["Text_Indigo_UltimateGoal"] = "MESETA AÑIL\\p¡El objetivo de todo ENTRENADOR:\nEl CG de la LIGA POKéMON!",
  ["Text_ItNeedsCardKey"] = "¡Caray!\n¡Necesito una LLAVE MAGNÉTICA!",
  ["Text_Kitchen"] = "¡Mmm, huele que alimenta!\nAquí han debido de cocinar algo...",
  ["Text_LightFilteringUseDive"] = "La luz se filtra desde la\nsuperficie. ¿Usas BUCEO?",
  ["Text_LikeProfileWayItIs"] = "Vale, pues déjalo como está.\\pA mí también me gusta.",
  ["Text_LookedAtPlayersTrainerCard"] = "¡Bingo! ¡Puedes mirar la FICHA\nde ENTRENADOR de {STR_VAR_1}!",
  ["Text_LookedAtPlayersTrainerCardColored"] = "¡Bingo! ¡Puedes mirar la FICHA\nde ENTRENADOR de {STR_VAR_1}!\\p¡Es de color {STR_VAR_2}!",
  ["Text_LooksLikeNothingHere"] = "Parece que aquí no hay nada...",
  ["Text_MayIHelpYou"] = "¡Hola! ¿Puedo ayudarte en algo?",
  ["Text_MomExplainHPGetPotions"] = "MAMÁ: ¡Muy bien! ¡Tú y tus\nPOKéMON estáis en plena forma!\\pMe ha dicho el PROF. OAK que la\nenergía de los POKéMON se mide\\lpor PS.\\pSi tus POKéMON pierden los PS,\npuedes recuperarlos en cualquier\\lCENTRO POKéMON.\\pPara viajes largos, los ENTRENA-\nDORES más espabilados compran\\punas cuantas POCIONES en la\nTIENDA POKéMON.\\p¡Demuestra a todos quien eres,\ncariño! ¡Cuídate mucho, tesoro!",
  ["Text_MonFlewAway"] = "¡El {STR_VAR_1} se ha marchado!",
  ["Text_MonMayGoUnderwater"] = "El mar es muy profundo en esta\nzona.\\lUn POKéMON podría bucear aquí.",
  ["Text_MonMayPushBoulder"] = "Es una roca enorme, pero un\nPOKéMON podría apartarla.",
  ["Text_MonMaySmashRock"] = "Es una roca muy dura, pero un\nPOKéMON podría hacerla añicos.",
  ["Text_MonMaySurface"] = "La luz se filtra desde la\nsuperficie.\\lUn POKéMON puede emerger aquí.",
  ["Text_MonSentToBoxBillsBoxFull"] = "La CAJA “{STR_VAR_3}” del PC\nde BILL estaba llena.\\p{STR_VAR_2} fue enviado a la CAJA\n“{STR_VAR_1}”.",
  ["Text_MonSentToBoxInBillsPC"] = "{STR_VAR_2} fue enviado al PC\nde BILL.\\pSe ha guardado en la CAJA\n“{STR_VAR_1}”.",
  ["Text_MonSentToBoxInSomeonesPC"] = "{STR_VAR_2} fue enviado al PC\nde alguien.\\pSe ha guardado en la CAJA\n“{STR_VAR_1}”.",
  ["Text_MonSentToBoxSomeonesBoxFull"] = "La CAJA “{STR_VAR_3}” del PC\nde alguien estaba llena.\\p{STR_VAR_2} fue enviado a la CAJA\n“{STR_VAR_1}”.",
  ["Text_MonUsedDive"] = "{STR_VAR_1} usó BUCEO.",
  ["Text_MonUsedMove"] = "{STR_VAR_1} usó {STR_VAR_2}.",
  ["Text_MonUsedStrengthCanMoveBoulders"] = "{STR_VAR_1} usó FUERZA.\\pLa FUERZA de {STR_VAR_1} logró\ndesplazar la roca a un lado.",
  ["Text_MonUsedWaterfall"] = "{STR_VAR_1} usó CASCADA.",
  ["Text_MonsHealed"] = "Tus POKéMON están de nuevo\nen forma.\\p¡Esperamos que te vaya bien!",
  ["Text_MonsHealedShouldBuyPotions"] = "Tus POKéMON están de nuevo\nen forma.\\pVen a vernos cuando la energía\nde tus POKéMON, los PS, estén\\lbajos de nivel.\\pCuando vayas a hacer un largo\nviaje, conviene que compres\\lPOCIONES en la TIENDA POKéMON.\\p¡Demuestra lo que vales!",
  ["Text_MoveCanOnlyBeLearnedOnce"] = "Este movimiento sólo se puede\naprender una vez, ¿vale?",
  ["Text_NeatlyLinedUpTools"] = "Hay un montón de relucientes\nherramientas muy bien ordenadas.",
  ["Text_NoMoreRoomForPokemon"] = "¡No queda sitio para más POKéMON!\\p¡Las CAJAS POKéMON están llenas!",
  ["Text_NoRoomForAnotherDecor"] = "¡Mala suerte! No queda sitio\npara {STR_VAR_2}...",
  ["Text_NothingToPutThemIn"] = "¡Vaya!\n¡No tienes MONEDERO!...",
  ["Text_ObtainedTheDecor"] = "¡Obtuviste {STR_VAR_2}!",
  ["Text_ObtainedTheX"] = "¡Obtuviste {STR_VAR_2}!",
  ["Text_OhThatsBadgeGoRightAhead"] = "¡Oh! ¡Ésa es la {STR_VAR_1}!\n¡Puedes pasar!",
  ["Text_OnlyDodrioAllowed"] = "“DODRIO A POR BAYAS”...\nYo creo que el nombre lo explica\\ltodo, ¿no?\\pPara jugar a este juego debes\ntener al menos un DODRIO.",
  ["Text_OnlyPassWithBadgeDontHaveYet"] = "¡Sólo podrás entrar aquí si tienes\nla {STR_VAR_1}!\\p¡Aún no tienes la {STR_VAR_1}!\\p¡Debes tenerla para acceder\na la LIGA POKéMON!",
  ["Text_OnlySkilledTrainersAllowedThrough"] = "Sólo pueden pasar los\nENTRENADORES expertos.\\p¡Aún no tienes la {STR_VAR_1}!",
  ["Text_OpenedPkmnStorage"] = "Acceso al Sistema de\nAlmacenamiento de POKéMON\\lconcedido.",
  ["Text_Painting"] = "Qué foto más bonita.\nEl POKéMON parece estar encantado.",
  ["Text_PlayWhichGame"] = "¿A qué juego quieres jugar?",
  ["Text_PlayerBootedUpPC"] = "{PLAYER} encendió el PC.",
  ["Text_PlayerFacingTVScreen"] = "¡Está saliendo un POKéMON\npor la tele! Se le ve encantado...",
  ["Text_PlayerIsPlayingRightNowGoForIt"] = "¡Parece que {STR_VAR_1} está jugando\nahora mismo! ¡Conéctate!",
  ["Text_PlayerObtainedTheMon"] = "¡{PLAYER} obtuvo\nel {STR_VAR_1}!",
  ["Text_PleaseComeAgain"] = "¡Vuelve cuando quieras!",
  ["Text_PokeMartShelf"] = "¡Uauu!\n¡Cantidad de artículos de POKéMON!",
  ["Text_PokecenterSign"] = "CENTRO POKéMON\n¡Cura a tus POKéMON!",
  ["Text_PokemartSign"] = "TIENDAS POKéMON\n¡Compra aquí todos tus objetos!",
  ["Text_PokemonJumpInfo"] = "“SALTO POKéMON”\\pConsigue que a tus POKéMON no les\natrape la LIANA usando el Botón A.\\pSólo pueden participar los POKéMON\nque midan unos 70 cm o menos.\\pA los POKéMON que naden despacio,\ncaven o vuelen no se les dará muy\\lbien lo de saltar.\\pPor ello, estos POKéMON no deben\nparticipar.\\pSi todos saltan a la vez,\npueden ocurrir cosas estupendas.",
  ["Text_PolishedWindow"] = "La ventana está requetelimpia.",
  ["Text_PowerPlantMachine"] = "¿Para qué servirá?\nPrefiero no tocar, por si acaso...",
  ["Text_ProfileSaysSomethingAboutYou"] = "Mmmm...\\pLa verdad es que te pega, da idea\nde cómo eres.\\p¡Ahora nos conocemos mejor!\n¡Vamos a llevarnos bien siempre!",
  ["Text_PutCoinsAwayInCoinCase"] = "{PLAYER} puso las FICHAS\nen el MONEDERO.",
  ["Text_PutItemAway"] = "{PLAYER} puso {STR_VAR_2}\nen el {STR_VAR_3}.",
  ["Text_QuestionnaireThankYou"] = "Gracias por rellenar el\ncuestionario. Usaremos tus\\lrespuestas a modo de referencia.",
  ["Text_RepelWoreOff"] = "El REPELENTE ha dejado de hacer\nefecto.",
  ["Text_RestoredPkmnToFullHealth"] = "Gracias por esperar.\\pMisión cumplida. Somos especialistas\nen devolver la forma a los\\lPOKéMON.",
  ["Text_SeaIsDeepUseDive"] = "El mar es muy profundo en esta\nzona. ¿Usas BUCEO?",
  ["Text_ShortJumpingPokemonAllowed"] = "En “SALTO POKéMON” pueden\nparticipar los POKéMON que midan\\lunos 70 cm o menos.\\pTampoco pueden participar los\nPOKéMON que no pueden saltar.\\pEs decir, los POKéMON que sólo\nnadan, cavan o vuelan.\\pBueno, pues ya lo sabes.",
  ["Text_Snacks"] = "Mmm, cuántas cosas ricas...",
  ["Text_StrengthMadeMovingBouldersPossible"] = "Usar FUERZA ha permitido desplazar\nla roca a un lado.",
  ["Text_TakeSeatStartBattle"] = "Puedes comenzar el combate.",
  ["Text_TakeSeatStartTrade"] = "Puedes comenzar el intercambio.",
  ["Text_TakeYourPkmnForFewSeconds"] = "Muy bien. Ten un poco de\npaciencia. Será sólo un momento.",
  ["Text_TalkToManToPlay"] = "Si quieres jugar a un juego,\ndíselo a mi compañero.",
