  ["sText_MirrorMoveFailed"] = "¡El MOV. ESPEJO ha fallado!",
  ["sText_MysteryGiftAlteringCave"] = "Gracias por usar el sistema\ndel REGALO MISTERIOSO.\\pÚltimamente se ha comentado que\nhan aparecido POKéMON raros.\\pDicen que ha sido por CUEVA\nCAMBIANTE y por ISLA AISLADA.\\p¿Por qué no te pasas por allí\ny ves si los rumores son ciertos?",
  ["sText_MysteryGiftBattleCountCard"] = "Gracias por usar el sistema\ndel REGALO MISTERIOSO.\\pTu TARJETA de RECUENTO de\nCOMBATES te muestra los récords\\pde los combates mantenidos con\nENTRENADORES que tienen la\\lmisma TARJETA.\\pBusca ENTRENADORES que\ntengan la misma TARJETA que tú.\\pCuando leas las NOTICIAS,\npodrás ver las clasificaciones.\\p¡No te lo pierdas!",
  ["sText_MysteryGiftBattleCountCard_2"] = "Gracias por usar el sistema\ndel REGALO MISTERIOSO.\\p¡Enhorabuena!\\p¡Has ganado un premio por vencer\na tu rival en tres combates!\\p¡Esperamos que sigas luchando!",
  ["sText_MysteryGiftEgg"] = "Gracias por usar el sistema\ndel REGALO MISTERIOSO.\\pTenemos un REGALO del CENTRO\nPOKéMON: ¡un HUEVO POKéMON!\\pCuídalo con tacto y cariño.",
  ["sText_MysteryGiftStampCard"] = "Gracias por usar el sistema\nde SELLOS.\\pPara completar la TARJETA\nde SELLOS, te faltan {STR_VAR_1}.",
  ["sText_MysteryGiftVisitingTrainer"] = "Gracias por usar el sistema\ndel REGALO MISTERIOSO.\\pAl llevar la TARJETA MISTERIOSA,\npodrás participar en una encuesta\\len la TIENDA POKéMON.\\pAprovecha las encuestas para\ninvitar a ENTRENADORES\\la ARCHI7.\\pVoy a darte una contraseña secreta\npara la encuesta:\\p“QUIERO ENTRENADORES\nMUY FUERTES”\\pEscríbela en un cuestionario y\nenvíala al sistema de comunicación\\linalámbrica.",
  ["sText_MysteryGiftVisitingTrainer_2"] = "Gracias por usar el sistema\ndel REGALO MISTERIOSO.\\pHa llegado un ENTRENADOR\na ARCHI7 y te está buscando.\\pEsperamos que disfrutes del\ncombate con el ENTRENADOR.\\pSi quieres, puedes invitar a más\nENTRENADORES usando otras\\lcontraseñas.\\pBusca otras contraseñas\nque vayan bien.",
  ["sText_MysticTicket1"] = "Parece que puedes usarlo en el\nPUERTO de CIUDAD CARMÍN.\\p¿Por qué no curioseas un poco\npara ver de qué se trata?",
